import{_ as e,o,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-Jun-7 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Jun-7 :: Ceph Performance Weekly","date":"2018-06-07T00:00:00.000Z","updated":"2018-06-08T00:00:00.000Z","tags":["Ceph","分布式存储","内存分配器优化","缓存策略","性能提升"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Jun-7_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Jun-7_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),i={name:"posts/2018/2018-Jun-7_-_-_Ceph_Performance_Weekly.md"};function n(s,l,a,p,_,g){return o(),t("div",null,[...l[0]||(l[0]=[r('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Igor、Adam、Radek、Josh、Igor、Sade等</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储系统开发进展，重点聚焦于内存分配器优化、缓存策略调整等议题。</p><p><strong>关键细节与议题</strong>：</p><ul><li><strong>内存分配器优化</strong>： <ul><li>Igor在位图分配器上进行改进，Adam负责审查。</li><li>探讨了新的“cash balance”工作，旨在优化内存使用。</li><li>提出了针对优先队列的优化建议，减少内存分配开销。</li><li>讨论了Intel和AMD处理器安全补丁对性能的影响。</li><li>探索使用自旋锁、测试优化和Intel TSX事务性内存提高性能的方案。</li></ul></li><li><strong>缓存策略调整</strong>： <ul><li>Igor介绍了基于优先级的缓存分配方案，按数据缓存、元数据和键值缓存的优先级进行内存分配。</li><li>讨论了基于年龄的缓存分箱方案，动态调整内存分配以适应不同场景。</li><li>探讨了将缓存策略应用于RocksDB缓存的可行性。</li></ul></li><li><strong>其他议题</strong>： <ul><li>讨论了性能测试和基准测试的重要性。</li><li>讨论了针对不同工作负载的优化策略。</li></ul></li></ul><p><strong>决定事项</strong>：</p><ul><li>继续优化内存分配器和缓存策略。</li><li>对现有代码进行性能测试和基准测试，评估优化效果。</li><li>探索使用TSX事务性内存提高性能的方案。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Igor改进位图分配器和缓存策略。</li><li>Adam继续审查Igor的工作。</li><li>Radek探索优化优先队列的方案。</li><li>Josh和Igor讨论将缓存策略应用于RocksDB缓存的可行性。</li><li>所有参会人员定期进行会议，讨论进展和问题。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了Ceph的多个组件和术语，如Rados、BlueStore、RBD、RocksDB、优先队列、缓存、内存分配器、TSX等。</li><li>讨论了性能优化和内存管理的多个方面，包括自旋锁、互斥锁、事务性内存、缓存策略等。</li></ul>',13)])])}const d=e(i,[["render",n]]);export{c as __pageData,d as default};
